import{_ as l,l as o,o as e,c as i,v as t,p as m,x as n,d as s,i as p,S as _}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Kalman 价差滤波","description":"","frontmatter":{"title":"Kalman 价差滤波","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/kalman-spread.md","filePath":"quant/kalman-spread.md","lastUpdated":1789023840000}'),u={name:"quant/kalman-spread.md"};function h(d,a,E,c,B,A){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="kalman-价差滤波" tabindex="-1">Kalman 价差滤波 <a class="header-anchor" href="#kalman-价差滤波" aria-label="Permalink to &quot;Kalman 价差滤波&quot;">​</a></h1><div class="epigraph"><p>把可观测价差写成隐均衡水平加噪声，或写成带均值回复的状态加量测误差；Kalman 给出的是过滤后的偏离，用来开仓，而不是把对冲比当成每天要重估的主状态。</p><footer>—— 线性滤波见 Kalman, 1960；状态空间计量见 Harvey, 1989；配对上把价差建成均值回复状态见 Elliott, Van Der Hoek and Malcolm, Quantitative Finance, 2005</footer></div><p><a href="/quant/copula-pairs">上一课</a>把边缘与依赖分开，用条件分位开仓，补的是非线性、不对称尾部；强依赖可以与 \\(I(1)\\) 价差共存，必须单独声明交易对象。缺口是价差的隐状态。原始 \\(e_t\\) 含微观结构噪声与缓慢漂移，直接算 Z-score 会把每一次跳动都当成均衡偏离；滤波平滑又含未来。本课把状态换成价差的均衡水平或潜在 OU，信号用预测步偏离。不重选 Copula 族。它与<a href="/quant/kalman-hedge">时变对冲比</a>正交，必须分开设 \\(Q\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>原始价差含微观结构噪声、隔夜跳空与短暂的流动性冲击。直接对 \\(e_t\\) 算 <a href="/quant/zscore-entry">Z-score</a>，等于把每一次跳动都当成均衡偏离。若真实均衡水平 \\(\\mu_t\\) 慢变（利率台阶、季节性、缓慢的相对基本面），固定均值会把制度漂移读成可交易 alpha。把 \\(\\mu_t\\) 写成随机游走或弱回复状态，</p> \\[\\mu_t=\\mu_{t-1}+\\eta_t,\\qquad e_t=\\mu_t+x_t,\\qquad x_t=\\phi x_{t-1}+\\varepsilon_t, \\]<p>或更紧地写成单状态 OU：量测是带噪声的价差，状态是潜在 OU。Kalman 输出 \\(\\hat\\mu_{t|t-1}\\) 与 \\(\\hat x_{t|t-1}\\)，开仓用过滤后的 \\(x\\) 而不是原始 \\(e\\)。问题是识别：观测到的一次跳，究竟是噪声（应忽略）、是可交易的 \\(x\\)（应开仓），还是 \\(\\mu\\) 变了（应改原点、不应开仓）。</p><p>这与时变 \\(\\beta\\) 的识别同构，但对象不同。调 \\(\\beta\\) 会改变价差的定义本身；调 \\(\\mu\\) 只改变价差的原点。前者在 <a href="/quant/hedge-ratio-break">对冲比断裂</a> 时更致命，后者在水平漂移时更致命。两者同时开、两个 \\(Q\\) 都大，价差被解释光，没有信号。</p><h3 id="可交易的是预测偏离" tabindex="-1">可交易的是预测偏离 <a class="header-anchor" href="#可交易的是预测偏离" aria-label="Permalink to &quot;可交易的是预测偏离&quot;">​</a></h3><p>滤波 \\(\\hat x_{t|t}\\) 用了当期 \\(e_t\\)。回测若在 \\(t\\) 用 \\(\\hat x_{t|t}\\) 开仓，含同期信息。可交易信号是 \\(\\hat x_{t|t-1}\\)，或用 \\(t-1\\) 的滤波状态加 \\(t\\) 的新价格之前先做预测步。平滑 \\(\\hat x_{t|T}\\) 会把未来的回归提前画出来，样本内几乎总是漂亮。Elliott 等人的贡献是把均值回复放进状态方程，使「过滤」与「交易的那条过程」是同一个似然；贡献不是允许使用平滑状态下单。</p><p><span class="marginnote">量测噪声 \\(R\\) 过小，滤波认为价差精确，几乎不平滑，退化成原始 \\(e\\) 的 Z-score。\\(R\\) 过大，状态紧跟，过滤后的 \\(x\\) 接近 0，永远不开仓。\\(Q_\\mu\\) 过大则原点跟着价差走，开仓信号被吃掉——这是「时变均值」最常见的过拟合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>规格 A：固定 \\(\\beta\\)，滤 \\(\\mu\\) 与 \\(x\\)。</strong> 形成期 OLS 或 Engle–Granger 得 \\(\\hat\\beta\\)，交易期冻结。状态 \\((\\mu_t,x_t)\\)，量测 \\(e_t=\\mu_t+x_t\\)。\\(x\\) 的转移系数 \\(\\phi=e^{-\\kappa\\Delta}\\) 可固定（用形成期 OU）或与 \\(Q,R\\) 一起用预测误差似然估计。冻结 \\(\\beta\\) 使本篇与 kalman-hedge 正交：这里不把缺口解释成对冲比变了。</p><p><strong>规格 B：单状态 OU 加量测噪声。</strong> 状态即潜在价差 \\(z_t\\)，</p> \\[z_t=\\mu(1-\\phi)+\\phi z_{t-1}+\\eta_t,\\qquad e_t=z_t+\\varepsilon_t. \\]<p>开仓用 \\((z_{t|t-1}-\\mu)/\\sigma_z\\)。当 \\(R=0\\)，退化为对原始价差做 AR(1)。\\(R\\gt 0\\) 相当于先低通再标准化，减少因单日跳空触发的假开仓。</p><p>超参数仍用 Harvey 的预测误差分解。不要用交易期 PnL 网格搜 \\(Q,R\\)。诊断：新息应近白；若新息仍有单位根，不是噪声太大，而是 \\(\\beta\\) 错了或协整已经破裂，应停止滤价差、回到 <a href="/quant/cointegration-break">协整破裂</a> 的检验，而不是把 \\(Q_\\mu\\) 开大把单位根吸进均值。</p><h3 id="与滚动均值、ewma-的等价" tabindex="-1">与滚动均值、EWMA 的等价 <a class="header-anchor" href="#与滚动均值、ewma-的等价" aria-label="Permalink to &quot;与滚动均值、EWMA 的等价&quot;">​</a></h3><p>对 \\(\\mu_t\\) 随机游走、无 \\(x\\) 分解的 Kalman，稳态下是 EWMA：增益由 \\(Q_\\mu/R\\) 决定。许多「自适应 Z-score」其实是这一退化。写出状态空间的好处是：可以把 \\(x\\) 的回复与 \\(\\mu\\) 的漂移分开，并给出状态方差——不确定度大时降低杠杆。滚动窗口均值对应一种硬切断的记忆；Kalman 是指数记忆。两者都在偏误–方差前线上，都不是协整定理。</p><p>执行时钟与 kalman-hedge 相同：用预测状态在次日或下一可交易中点开仓。盘中滤价差需要同步中点，跳空时量测缺失或方差放大，应只做预测步。A 股涨跌停使 \\(e_t\\) 截断，量测模型应承认截断，否则状态会为了拟合板上的钉住值而扭曲。</p><p><span class="marginnote">把 Kalman 滤过的价差再套一层布林带或 MACD，是把同一低通重复两次，并多了一组不可比的超参。信号应直接来自标准化的 \\(\\hat x_{t|t-1}\\)。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kalman 增益把新息按「状态不确定 vs 量测噪声」写入 \\(\\mu\\) 或 \\(x\\)。设计矩阵决定写入哪一个：若模型里 \\(x\\) 回复快、\\(\\mu\\) 几乎常数，短暂缺口进 \\(x\\)，成为可交易偏离；若 \\(Q_\\mu\\) 被估得很大，同一缺口进 \\(\\mu\\)，原点搬家，不交易。样本内似然往往偏好较大的 \\(Q_\\mu\\)，因为这样拟合更好——而这正会榨干交易信号。所以价差滤波的超参数应在形成期估、交易期冻结，与 GGR 把 \\(\\sigma\\) 钉在形成期是同一纪律。</p><p>机制上的第二句话是噪声的来源。买卖弹跳、非同步、指数套利流量，使 \\(e_t\\) 的高频成分不像 OU。<a href="/quant/effective-realized-spread">有效价差</a> 量级的跳动不应触发开仓；\\(R\\) 的数量级至少应覆盖半价差，而不是用收盘价的样本方差去估一个过小的 \\(R\\)。过滤因此首先是执行友好：少在噪声上换手，而不是提高信息比率的魔法。</p><h3 id="何时不该滤价差、该调" tabindex="-1">何时不该滤价差、该调 \\(\\beta\\) <a class="header-anchor" href="#何时不该滤价差、该调" aria-label="Permalink to &quot;何时不该滤价差、该调 $\\beta$&quot;">​</a></h3><p>滤波价差假定线性组合的系数对。成分股权重变、一只腿换了业务、期现乘数或 ETF 份额变，缺口来自 \\(\\beta\\)，不是来自 \\(\\mu\\)。此时加大 \\(Q_\\mu\\) 会把错误对冲比吸收成「新均衡」，看起来残差很稳，经济上你已经在用错误的腿数做空。诊断是：\\(\\hat\\beta\\) 与滚动 OLS 分道、或 Gregory–Hansen 拒绝稳定协整。应切换到 kalman-hedge 或停止交易，而不是把价差原点再平滑一次。反过来，分红、拆股应在观测方程里显式调整，不要让 \\(\\mu\\) 去吸收公司行为。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要同时让 \\(\\beta_t\\)、\\(\\mu_t\\)、\\(x_t\\) 都成为高噪声状态：不可识别。典型分工：经济上 \\(\\beta\\) 该稳（转换比率、固定篮子权重）则滤价差；\\(\\beta\\) 该变（统计篮子、行业权重）则滤对冲比，价差阈值建在预测残差上。两者都变时，需要更多量测（多对价格）或更强的先验。不要用平滑路径画「当时该不该开仓」。不要把状态方差当成组合 VaR。</p><p>与 <a href="/quant/ou-spread">OU 价差</a> 的关系：OU 是 DGP 假设；Kalman 是在该假设（或带噪声的该假设）下的递归估计。半衰期应在预测残差上估，否则描述的是另一条序列。成本后比较的是：滤过的信号是否减少了假开仓、是否补偿了滞后。过滤引入滞后，在真回归很快时会吃掉边缘；这是 \\(R\\) 的代价，不是 bug。</p><p><span class="marginnote">Elliott, Van Der Hoek and Malcolm（2005）把对冲比与均值回复放进同一状态空间。复制时若只实现了滤 \\(\\beta\\)、却用原始价差开仓，或只滤了价差却让 \\(\\beta\\) 每日 OLS，都不是原文系统，也不能用他们的示意路径当绩效。</span></p>',30)),(e(),m(_,null,{default:n(()=>[p(r,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20YX%5B%22%E4%BB%B7%E6%A0%BC%20y%2C%20x%22%5D%20--%3E%20BETA%5B%22%E5%86%BB%E7%BB%93%E6%88%96%E7%BC%93%E5%8F%98%E7%9A%84%20%CE%B2%22%5D%0A%20%20BETA%20--%3E%20E%5B%22%E8%A7%82%E6%B5%8B%E4%BB%B7%E5%B7%AE%20e%22%5D%0A%20%20E%20--%3E%20KF%5B%22Kalman%20%E9%A2%84%E6%B5%8B%E6%AD%A5%22%5D%0A%20%20KF%20--%3E%20MU%5B%22%E5%9D%87%E8%A1%A1%E6%B0%B4%E5%B9%B3%20%CE%BC%22%5D%0A%20%20KF%20--%3E%20XST%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E5%81%8F%E7%A6%BB%20x%22%5D%0A%20%20XST%20--%3E%20Z%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E5%90%8E%E5%BC%80%E5%B9%B3%22%5D%0A%20%20Q%5B%22Q_%CE%BC%20vs%20Q_x%20vs%20R%22%5D%20--%3E%20ID%5B%22%E8%AF%86%E5%88%AB%3A%20%E5%8E%9F%E7%82%B9%E5%8F%98%20%2F%20%E5%8F%AF%E4%BA%A4%E6%98%93%20%2F%20%E5%99%AA%E5%A3%B0%22%5D%0A%20%20ID%20--%3E%20KF%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kalman 价差滤波的状态是价差的均衡水平或潜在 OU，不是对冲比；与 <a href="/quant/kalman-hedge">时变对冲比</a> 正交，必须分开设 \\(Q\\)。</li><li>可交易信号用预测步偏离；滤波平滑含未来，不能进撮合。</li><li>\\(Q_\\mu\\) 过大则无信号，\\(R\\) 过小则不过滤噪声；超参数应在形成期估、交易期冻结。</li><li>新息若仍像单位根，问题在 \\(\\beta\\) 或协整破裂，不是把均值再平滑一次。</li><li>出处：Kalman, 1960；Harvey, 1989；Elliott, Van Der Hoek and Malcolm, <em>Quantitative Finance</em>, 2005。</li></ul>',2))])}const q=l(u,[["render",h]]);export{b as __pageData,q as default};
